        name=group["id"]+"-"+suffix
        info=byname[name]
        assert sha(info["file"])==info["sha256"]
        im=Image.open(info["file"])
        assert list(im.size)==info["pixels"] and info["pixelScale"]==1 and info["resized"]==False
